'use client'

import Image from 'next/image'
import {useEffect,useMemo,useRef,useState} from 'react'
import {supabase,type Member,type Student,type Cash,type Tx,type Bill,type School,type Payment} from '@/lib/supabase'
import {BarChart3,BookOpen,Building2,Download,Eye,FileText,GraduationCap,LayoutDashboard,LogOut,Menu,Moon,Pencil,Plus,ReceiptText,Settings,Sun,Upload,Users,WalletCards,X} from 'lucide-react'
import {Bar,BarChart,CartesianGrid,ResponsiveContainer,Tooltip,XAxis,YAxis} from 'recharts'

type View='dashboard'|'finance'|'students'|'bills'|'budget'|'reports'|'team'|'settings'|'owner'
type Toast={kind:'ok'|'error';text:string}|null
type ImportedStudent={nis:string;nisn:string;name:string;className:string;guardianName:string;phone:string;line:number}
const money=(n:number)=>new Intl.NumberFormat('id-ID',{style:'currency',currency:'IDR',maximumFractionDigits:0}).format(n||0)
const date=()=>new Date().toISOString().slice(0,10)
const number=(prefix:string)=>`${prefix}-${Date.now().toString().slice(-10)}`
const INCOME_CATEGORIES=['SPP','Uang gedung','Daftar ulang','Donasi','Bantuan pemerintah','Hasil usaha sekolah']
const EXPENSE_CATEGORIES=['ATK & perlengkapan','Gaji & honor','Listrik, air & internet','Pemeliharaan','Kegiatan siswa','Transportasi','Konsumsi','Pembelian aset']
const CUSTOM='__custom__'
const loginEmail=(value:string)=>{const input=value.trim().toLowerCase();if(/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(input))return input;const slug=input.normalize('NFKD').replace(/[^a-z0-9._-]+/g,'-').replace(/^[._-]+|[._-]+$/g,'');return slug?`${slug}@akun.sikaspro.id`:''}
const authProblem=(message:string)=>{if(/invalid login credentials/i.test(message))return'Username atau password salah. Periksa kembali penulisannya.';if(/email not confirmed/i.test(message))return'Akun belum aktif. Hubungi pengelola jika akun dibuat sebelum perbaikan ini.';if(/rate limit|too many/i.test(message))return'Terlalu banyak percobaan. Tunggu beberapa menit lalu coba lagi.';if(/failed to fetch|network/i.test(message))return'Koneksi ke server bermasalah. Periksa internet lalu coba kembali.';return message||'Terjadi masalah yang belum diketahui. Silakan coba lagi.'}
const uploadProof=async(schoolId:string,file:File)=>{if(!file?.size)return null;if(file.size>5*1024*1024)throw new Error('Ukuran bukti maksimal 5 MB.');const path=`${schoolId}/${Date.now()}-${file.name.replace(/[^a-zA-Z0-9._-]/g,'-')}`;const {error}=await supabase.storage.from('transaction-proofs').upload(path,file);if(error)throw error;return path}
const showProof=async(path:string|null|undefined,notify:(s:string,k?:'ok'|'error')=>void)=>{if(!path)return notify('Foto bukti belum tersedia untuk pembayaran ini.','error');const {data,error}=await supabase.storage.from('transaction-proofs').createSignedUrl(path,300);if(error)return notify(`Bukti tidak dapat dibuka: ${error.message}`,'error');window.open(data.signedUrl,'_blank','noopener,noreferrer')}

export function SikasApp(){
 const [ready,setReady]=useState(false),[userId,setUserId]=useState<string|null>(null),[member,setMember]=useState<Member|null>(null),[isSuper,setIsSuper]=useState(false),[view,setView]=useState<View>('dashboard'),[toast,setToast]=useState<Toast>(null),[dark,setDark]=useState(()=>typeof window!=='undefined'&&localStorage.theme==='dark'),[menu,setMenu]=useState(false)
 const notify=(text:string,kind:'ok'|'error'='ok')=>{setToast({text,kind});setTimeout(()=>setToast(null),3500)}
 const reload=async(id?:string)=>{const uid=id||userId;if(!uid)return;const [membership,profile]=await Promise.all([supabase.from('school_members').select('school_id,role,status,created_at,schools(*)').eq('user_id',uid).eq('status','active').order('created_at',{ascending:true}).limit(1).maybeSingle(),supabase.from('profiles').select('is_super_admin').eq('id',uid).single()]);if(membership.error)notify(`Data sekolah gagal dibuka: ${membership.error.message}`,'error');setMember((membership.data as unknown as Member)||null);setIsSuper(Boolean(profile.data?.is_super_admin))}
 useEffect(()=>{let alive=true;supabase.auth.getSession().then(async({data,error})=>{if(!alive)return;if(error)notify(`Sesi login bermasalah: ${error.message}`,'error');const id=data.session?.user.id||null;setUserId(id);if(id){void supabase.rpc('mark_active');await reload(id)}if(alive)setReady(true)});const {data}=supabase.auth.onAuthStateChange((_e,s)=>{const id=s?.user.id||null;setUserId(id);if(id){void supabase.rpc('mark_active');void reload(id)}else{setMember(null);setIsSuper(false)}});return()=>{alive=false;data.subscription.unsubscribe()}},[])
 useEffect(()=>{document.documentElement.dataset.theme=dark?'dark':'light';localStorage.theme=dark?'dark':'light'},[dark])
 if(!ready)return <Splash/>
 if(!userId)return <Auth onDone={(id)=>{setUserId(id);reload(id)}} notify={notify}/>
 if(isSuper&&!member)return <OwnerApp onLogout={async()=>{await supabase.auth.signOut();setUserId(null);setIsSuper(false)}}/>
 if(!member)return <Onboarding userId={userId} onDone={()=>reload()} notify={notify}/>
 const role=member.role,school=member.schools
 const nav:[View,string,React.ReactNode][]=[['dashboard','Beranda',<LayoutDashboard key="d"/>],['finance','Keuangan',<WalletCards key="f"/>],['students','Siswa',<GraduationCap key="s"/>],['bills','Tagihan',<ReceiptText key="b"/>],['budget','Anggaran',<BarChart3 key="a"/>],['reports','Laporan',<FileText key="r"/>],...(role==='principal'?[['team','Tim Sekolah',<Users key="t"/>] as [View,string,React.ReactNode]]:[]),['settings','Pengaturan',<Settings key="g"/>]]
 const logout=async()=>{if(!confirm('Keluar dari akun di perangkat ini?'))return;await supabase.auth.signOut();setUserId(null);setMember(null)}
 return <div className="app-shell">
  <aside className={menu?'sidebar open':'sidebar'}><button className="close-mobile" onClick={()=>setMenu(false)}><X/></button><Brand compact/><div className="school-pill"><Building2/><span><b>{school.name}</b><small>{role==='principal'?'Kepala Sekolah':'Bendahara / Staf'}</small></span></div><nav>{nav.map(([id,label,icon])=><button key={id} className={view===id?'active':''} onClick={()=>{setView(id);setMenu(false)}}>{icon}<span>{label}</span></button>)}</nav><button className="logout" onClick={logout}><LogOut/>Keluar</button></aside>
  {menu&&<button className="backdrop" aria-label="Tutup menu" onClick={()=>setMenu(false)}/>}<main><header><button className="icon mobile" onClick={()=>setMenu(true)}><Menu/></button><div><h1>{nav.find(n=>n[0]===view)?.[1]}</h1><p>{school.academic_year}</p></div><span className="grow"/><button className="icon" onClick={()=>setDark(!dark)}>{dark?<Sun/>:<Moon/>}</button></header>
  <div className="content">{view==='dashboard'&&<Dashboard school={school}/>} {view==='finance'&&<Finance school={school} notify={notify}/>} {view==='students'&&<Students school={school} notify={notify}/>} {view==='bills'&&<Bills school={school} notify={notify}/>} {view==='budget'&&<Budget school={school} notify={notify}/>} {view==='reports'&&<Reports school={school} notify={notify}/>} {view==='team'&&<Team school={school} notify={notify}/>} {view==='settings'&&<SchoolSettings school={school} role={role} notify={notify}/>} {view==='owner'&&<Owner/>}</div></main>
  <nav className="bottom-nav">{nav.slice(0,5).map(([id,label,icon])=><button key={id} className={view===id?'active':''} onClick={()=>setView(id)}>{icon}<small>{label}</small></button>)}</nav>{toast&&<div className={`toast ${toast.kind}`}>{toast.text}</div>}
 </div>
}

function Brand({compact=false}:{compact?:boolean}){return <div className={compact?'brand compact':'brand'}><Image src="/logo.jpg" alt="Bantu Beres" width={compact?48:72} height={compact?48:72}/><span><b>Bantu Beres</b><strong>SIKAS Pro</strong>{!compact&&<small>Keuangan Sekolah</small>}</span></div>}
function Splash(){return <div className="center"><Brand/><span className="spinner"/></div>}

function Auth({onDone,notify}:{onDone:(id:string)=>void;notify:(s:string,k?:'ok'|'error')=>void}){
 const [mode,setMode]=useState<'login'|'signup'>('login'),[busy,setBusy]=useState(false),[problem,setProblem]=useState('')
 const changeMode=(next:'login'|'signup')=>{setMode(next);setProblem('')}
 const fail=(message:string)=>{const text=authProblem(message);setProblem(text);notify(text,'error')}
 const submit=async(e:React.FormEvent<HTMLFormElement>)=>{e.preventDefault();setBusy(true);setProblem('');const fd=new FormData(e.currentTarget),identifier=String(fd.get('identifier')).trim(),password=String(fd.get('password')),email=loginEmail(identifier);try{if(!email)return fail('Username tidak valid. Gunakan minimal 3 huruf atau angka.');if(mode==='signup'){const {data,error}=await supabase.functions.invoke('register-username',{body:{identifier,password,fullName:String(fd.get('full_name'))}});if(error)return fail(error.message);if(!data?.ok)return fail(data?.error||'Akun tidak berhasil dibuat.')}const result=await supabase.auth.signInWithPassword({email,password});if(result.error)return fail(result.error.message);notify(mode==='login'?'Berhasil masuk':'Akun berhasil dibuat dan langsung masuk');onDone(result.data.user.id)}catch(error){fail(error instanceof Error?error.message:'Terjadi masalah saat memproses akun.')}finally{setBusy(false)}}
 return <div className="auth-page"><section className="auth-hero"><Brand/><h1>Keuangan sekolah<br/><em>lebih tertib.</em></h1><p>Transaksi, tagihan, tunggakan, anggaran, kwitansi dan laporan dalam satu tempat yang aman.</p><div className="hero-points"><span>✓ Satu pintu transaksi</span><span>✓ Laporan otomatis</span><span>✓ Nyaman di HP</span></div></section><section className="auth-card"><div className="tabs"><button type="button" className={mode==='login'?'active':''} onClick={()=>changeMode('login')}>Masuk</button><button type="button" className={mode==='signup'?'active':''} onClick={()=>changeMode('signup')}>Daftar</button></div><h2>{mode==='login'?'Selamat datang':'Buat akun kepala sekolah'}</h2><p>{mode==='login'?'Masuk menggunakan username dan password.':'Akun langsung aktif dan otomatis menjadi Kepala Sekolah.'}</p><form onSubmit={submit}>{mode==='signup'&&<Field label="Nama lengkap" name="full_name" autoComplete="name" required/>}<Field label="Username" name="identifier" type="text" autoComplete="username" placeholder="Contoh: kepsek01" minLength={3} required/><Field label="Password" name="password" type="password" autoComplete={mode==='login'?'current-password':'new-password'} minLength={8} required/>{problem&&<div className="form-error" role="alert"><b>{mode==='login'?'Tidak bisa masuk':'Tidak bisa membuat akun'}</b><span>{problem}</span></div>}<button className="primary" disabled={busy}>{busy?'Memproses…':mode==='login'?'Masuk':'Buat akun'}</button></form><small className="hint">Username tidak harus berupa email asli. Simpan username dan password untuk login berikutnya.</small></section></div>
}

function Onboarding({onDone,notify}:{userId:string;onDone:()=>void;notify:(s:string,k?:'ok'|'error')=>void}){
 const [busy,setBusy]=useState(false),params=new URLSearchParams(typeof location==='undefined'?'':location.search),invite=params.get('invite')
 const accept=async()=>{setBusy(true);const {error}=await supabase.rpc('accept_invitation',{raw_token:invite});setBusy(false);if(error)return notify(error.message,'error');history.replaceState({},'',location.pathname);notify('Undangan diterima');onDone()}
 const create=async(e:React.FormEvent<HTMLFormElement>)=>{e.preventDefault();setBusy(true);const f=new FormData(e.currentTarget);const {error}=await supabase.rpc('create_school',{school_name:f.get('name'),school_npsn:f.get('npsn'),school_address:f.get('address'),school_city:f.get('city'),year_label:f.get('year')});setBusy(false);if(error)return notify(error.message,'error');notify('Workspace sekolah berhasil dibuat');onDone()}
 return <div className="onboard"><Brand/><div className="onboard-card">{invite?<><span className="eyebrow">UNDANGAN TIM</span><h1>Bergabung sebagai Bendahara/Staf</h1><p>Terima undangan untuk memperoleh akses ke ruang keuangan sekolah.</p><button className="primary" onClick={accept} disabled={busy}>{busy?'Memproses…':'Terima undangan'}</button></>:<><span className="eyebrow">LANGKAH PERTAMA</span><h1>Siapkan workspace sekolah</h1><p>Informasi ini akan digunakan pada dashboard, laporan dan kwitansi.</p><form onSubmit={create}><Field label="Nama sekolah" name="name" required/><div className="two"><Field label="NPSN" name="npsn"/><Field label="Tahun pelajaran" name="year" defaultValue="2026/2027" required/></div><Field label="Alamat" name="address"/><Field label="Kota / Kabupaten" name="city"/><button className="primary" disabled={busy}>{busy?'Membuat…':'Buat workspace sekolah'}</button></form></>}</div></div>
}

function Dashboard({school}:{school:School}){
 const [tx,setTx]=useState<Tx[]>([]),[bills,setBills]=useState<Bill[]>([]),[students,setStudents]=useState(0)
 useEffect(()=>{Promise.all([supabase.from('transactions').select('*').eq('school_id',school.id).eq('status','posted'),supabase.from('bills').select('*').eq('school_id',school.id),supabase.from('students').select('*',{count:'exact',head:true}).eq('school_id',school.id).eq('status','active')]).then(([a,b,c])=>{setTx((a.data||[]) as Tx[]);setBills((b.data||[]) as Bill[]);setStudents(c.count||0)})},[school.id])
 const income=tx.filter(x=>x.kind==='income').reduce((a,b)=>a+Number(b.amount),0),expense=tx.filter(x=>x.kind==='expense').reduce((a,b)=>a+Number(b.amount),0),arrears=bills.reduce((a,b)=>a+Number(b.amount)-Number(b.paid_amount),0)
 const chart=useMemo(()=>Array.from({length:6},(_,i)=>{const d=new Date();d.setMonth(d.getMonth()-5+i);const key=d.toISOString().slice(0,7);return{month:d.toLocaleDateString('id-ID',{month:'short'}),masuk:tx.filter(t=>t.tx_date.startsWith(key)&&t.kind==='income').reduce((a,b)=>a+Number(b.amount),0),keluar:tx.filter(t=>t.tx_date.startsWith(key)&&t.kind==='expense').reduce((a,b)=>a+Number(b.amount),0)}}),[tx])
 return <><section className="welcome"><div><span className="eyebrow">RINGKASAN SEKOLAH</span><h2>Selamat datang di SIKAS Pro</h2><p>Pantau keadaan keuangan {school.name} dari satu dashboard.</p></div><span className="period">Data hari ini<br/><b>{new Date().toLocaleDateString('id-ID',{dateStyle:'long'})}</b></span></section><div className="stats"><Stat label="Total pemasukan" value={money(income)} tone="green"/><Stat label="Total pengeluaran" value={money(expense)} tone="red"/><Stat label="Saldo berjalan" value={money(income-expense)} tone="blue"/><Stat label="Total tunggakan" value={money(arrears)} tone="orange"/></div><div className="grid-2"><Card title="Arus kas 6 bulan"><div className="chart"><ResponsiveContainer><BarChart data={chart}><CartesianGrid strokeDasharray="3 3" vertical={false}/><XAxis dataKey="month"/><YAxis hide/><Tooltip formatter={(v)=>money(Number(v))}/><Bar dataKey="masuk" fill="#2563eb" radius={[5,5,0,0]}/><Bar dataKey="keluar" fill="#f97316" radius={[5,5,0,0]}/></BarChart></ResponsiveContainer></div></Card><Card title="Kondisi cepat"><div className="quick-list"><p><span>Siswa aktif</span><b>{students}</b></p><p><span>Transaksi tercatat</span><b>{tx.length}</b></p><p><span>Tagihan aktif</span><b>{bills.filter(b=>b.status!=='paid').length}</b></p><p><span>Status kas</span><b className={income-expense>=0?'positive':'negative'}>{income-expense>=0?'Sehat':'Perlu perhatian'}</b></p></div></Card></div></>
}

function Finance({school,notify}:{school:School;notify:(s:string,k?:'ok'|'error')=>void}){
 const [items,setItems]=useState<Tx[]>([]),[cash,setCash]=useState<Cash[]>([]),[activities,setActivities]=useState<{id:string;name:string}[]>([]),[editing,setEditing]=useState<Tx|null>(null),[modal,setModal]=useState(false),[kind,setKind]=useState<'income'|'expense'>('income'),[busy,setBusy]=useState(false),[cashChoice,setCashChoice]=useState(''),[categoryChoice,setCategoryChoice]=useState('')
 const load=()=>Promise.all([supabase.from('transactions').select('*').eq('school_id',school.id).order('tx_date',{ascending:false}),supabase.from('cash_accounts').select('*').eq('school_id',school.id).eq('active',true).order('created_at'),supabase.from('activities').select('id,name').eq('school_id',school.id)]).then(([a,b,c])=>{if(a.error||b.error||c.error)return notify(`Data keuangan gagal dimuat: ${(a.error||b.error||c.error)?.message}`,'error');setItems((a.data||[]) as Tx[]);setCash((b.data||[]) as Cash[]);setActivities(c.data||[])})
 useEffect(()=>{load()},[school.id])
 const open=(next:'income'|'expense',tx?:Tx)=>{setKind(next);setEditing(tx||null);setCashChoice(tx?.cash_account_id||cash[0]?.id||'');const categories=next==='income'?INCOME_CATEGORIES:EXPENSE_CATEGORIES;setCategoryChoice(tx?(categories.includes(tx.category)?tx.category:CUSTOM):categories[0]);setModal(true)}
 const save=async(e:React.FormEvent<HTMLFormElement>)=>{e.preventDefault();setBusy(true);try{const f=new FormData(e.currentTarget),customCash=String(f.get('custom_cash')||'').trim(),customCategory=String(f.get('custom_category')||'').trim(),activityName=String(f.get('activity_name')||'').trim();let cashId=String(f.get('cash')||'');if(cashId===CUSTOM){if(!customCash)throw new Error('Tulis nama kas, E-Wallet, atau rekening custom.');const existing=cash.find(c=>c.name.toLowerCase()===customCash.toLowerCase());if(existing)cashId=existing.id;else{const {data,error}=await supabase.from('cash_accounts').insert({school_id:school.id,name:customCash,type:'custom'}).select('id').single();if(error)throw error;cashId=data.id}}const category=categoryChoice===CUSTOM?customCategory:String(f.get('category')||'');if(!category)throw new Error('Pilih kategori atau tulis kategori custom.');const proof=await uploadProof(school.id,f.get('proof') as File),activity=activities.find(a=>a.name.toLowerCase()===activityName.toLowerCase());const common={tx_date:f.get('date'),kind,cash_account_id:cashId,activity_id:activity?.id||null,activity_name:activityName||null,category,description:f.get('description'),amount:Number(f.get('amount')),...(proof?{proof_path:proof}:{})};if(editing){const {error}=await supabase.from('transactions').update(common).eq('id',editing.id).eq('school_id',school.id);if(error)throw error}else{const {data:{user}}=await supabase.auth.getUser();if(!user)throw new Error('Sesi login berakhir. Silakan masuk kembali.');const {error}=await supabase.from('transactions').insert({...common,school_id:school.id,number:number(kind==='income'?'IN':'OUT'),created_by:user.id});if(error)throw error}notify(editing?'Transaksi berhasil diperbarui':'Transaksi berhasil disimpan');setModal(false);setEditing(null);await load()}catch(error){notify(`Transaksi belum tersimpan: ${error instanceof Error?error.message:'Kesalahan tidak diketahui'}`,'error')}finally{setBusy(false)}}
 const voidTx=async(id:string)=>{const reason=prompt('Alasan pembatalan transaksi:');if(!reason)return;const {error}=await supabase.from('transactions').update({status:'void',void_reason:reason}).eq('id',id);if(error)return notify(error.message,'error');notify('Transaksi dibatalkan');load()}
 const categories=kind==='income'?INCOME_CATEGORIES:EXPENSE_CATEGORIES
 return <><Toolbar title="Buku transaksi" text="Semua pemasukan dan pengeluaran dicatat dari sini."><button className="secondary" onClick={()=>open('expense')}><Plus/>Pengeluaran</button><button className="primary small" onClick={()=>open('income')}><Plus/>Pemasukan</button></Toolbar><Card><DataTable headers={['Tanggal','Nomor','Keterangan','Kategori','Jenis','Nominal','Aksi']} rows={items.map(t=>[t.tx_date,t.number,t.description,t.category,<Badge key="b" tone={t.status==='void'?'muted':t.kind==='income'?'green':'red'}>{t.status==='void'?'Batal':t.kind==='income'?'Masuk':'Keluar'}</Badge>,money(Number(t.amount)),<span key="a" className="actions"><button className="link" onClick={()=>open(t.kind==='income'?'income':'expense',t)}><Pencil/>Edit</button>{t.proof_path&&<button className="link" onClick={()=>showProof(t.proof_path,notify)}><Eye/>Bukti</button>}{t.status==='posted'&&<button className="link danger" onClick={()=>voidTx(t.id)}>Batalkan</button>}</span>])}/></Card>{modal&&<Modal title={`${editing?'Edit':'Catat'} ${kind==='income'?'pemasukan':'pengeluaran'}`} onClose={()=>{setModal(false);setEditing(null)}}><form onSubmit={save}><div className="two"><Field label="Tanggal" name="date" type="date" defaultValue={editing?.tx_date||date()} required/><label className="field"><span>Kas / E-Wallet / rekening</span><select name="cash" value={cashChoice} onChange={e=>setCashChoice(e.target.value)} required><option value="" disabled>Pilih tempat dana</option>{cash.map(c=><option key={c.id} value={c.id}>{c.name}</option>)}<option value={CUSTOM}>+ Tulis custom</option></select></label></div>{cashChoice===CUSTOM&&<Field label="Nama kas / akun custom" name="custom_cash" placeholder="Contoh: Bank BRI BOS" required/>}{kind==='expense'&&<Field label="Kegiatan (boleh ditulis bebas)" name="activity_name" list="activity-history" defaultValue={editing?.activity_name||activities.find(a=>a.id===editing?.activity_id)?.name||''} placeholder="Contoh: Pentas seni 2026"/>}<datalist id="activity-history">{activities.map(a=><option key={a.id} value={a.name}/>)}</datalist><label className="field"><span>Kategori kebutuhan</span><select name="category" value={categoryChoice} onChange={e=>setCategoryChoice(e.target.value)} required><option value="" disabled>Pilih kategori</option>{categories.map(c=><option key={c}>{c}</option>)}<option value={CUSTOM}>+ Tulis kategori custom</option></select></label>{categoryChoice===CUSTOM&&<Field label="Kategori custom" name="custom_category" defaultValue={editing&&!categories.includes(editing.category)?editing.category:''} placeholder="Contoh: Seragam lomba" required/>}<Field label="Keterangan" name="description" defaultValue={editing?.description||''} placeholder="Contoh: Pembelian 5 rim kertas" required/><MoneyField label="Nominal" name="amount" defaultValue={editing?.amount} required/><Field label={`Bukti transaksi ${editing?'(kosongkan jika tidak diganti)':'(opsional, maks. 5 MB)'}`} name="proof" type="file" accept="image/jpeg,image/png,image/webp,application/pdf"/><button className="primary" disabled={busy}>{busy?'Menyimpan…':'Simpan transaksi'}</button></form></Modal>}</>
}

function Students({school,notify}:{school:School;notify:(s:string,k?:'ok'|'error')=>void}){
 const [items,setItems]=useState<Student[]>([]),[classes,setClasses]=useState<{id:string;name:string}[]>([]),[modal,setModal]=useState(false),[editing,setEditing]=useState<Student|null>(null),[busy,setBusy]=useState(false),[importing,setImporting]=useState(false),[importNote,setImportNote]=useState<{kind:'ok'|'error';text:string}|null>(null)
 const fileRef=useRef<HTMLInputElement>(null)
 const load=()=>Promise.all([supabase.from('students').select('*,classes(name)').eq('school_id',school.id).order('name'),supabase.from('classes').select('*').eq('school_id',school.id).eq('active',true)]).then(([a,b])=>{setItems((a.data||[]) as Student[]);setClasses(b.data||[])})
 useEffect(()=>{load()},[school.id])
 const addClass=async()=>{const name=prompt('Nama kelas baru:');if(!name)return;const {error}=await supabase.from('classes').insert({school_id:school.id,name});if(error)return notify(error.message,'error');notify('Kelas ditambahkan');load()}
 const save=async(e:React.FormEvent<HTMLFormElement>)=>{e.preventDefault();setBusy(true);try{const f=new FormData(e.currentTarget),className=String(f.get('class_name')||'').trim();let classId:string|null=null;if(className){const found=classes.find(c=>c.name.toLowerCase()===className.toLowerCase());if(found)classId=found.id;else{const {data,error}=await supabase.from('classes').insert({school_id:school.id,name:className}).select('id').single();if(error)throw error;classId=data.id}}const payload={nis:f.get('nis'),nisn:f.get('nisn')||null,name:f.get('name'),class_id:classId,guardian_name:f.get('guardian_name')||null,guardian_phone:f.get('guardian_phone')||null};const result=editing?await supabase.from('students').update(payload).eq('id',editing.id).eq('school_id',school.id):await supabase.from('students').insert({...payload,school_id:school.id});if(result.error)throw result.error;notify(editing?'Data siswa diperbarui':'Siswa ditambahkan');setModal(false);setEditing(null);await load()}catch(error){notify(`Data siswa belum tersimpan: ${error instanceof Error?error.message:'Kesalahan tidak diketahui'}`,'error')}finally{setBusy(false)}}
 const importExcel=async(e:React.ChangeEvent<HTMLInputElement>)=>{const file=e.target.files?.[0];e.target.value='';if(!file)return;setImporting(true);setImportNote(null);try{
  if(file.size>5*1024*1024)throw new Error('Ukuran file maksimal 5 MB.')
  const XLSX=await import('xlsx'),book=XLSX.read(await file.arrayBuffer(),{type:'array'}),sheet=book.Sheets['Data Siswa']||book.Sheets[book.SheetNames[0]]
  if(!sheet)throw new Error('File tidak memiliki lembar data.')
  const matrix=XLSX.utils.sheet_to_json<unknown[]>(sheet,{header:1,defval:'',raw:false}),key=(v:unknown)=>String(v??'').trim().toLowerCase().normalize('NFKD').replace(/[^a-z0-9]/g,''),clean=(v:unknown)=>String(v??'').trim()
  const aliases:Record<string,string>={nis:'nis',nisn:'nisn',nama:'name',namalengkap:'name',kelas:'className',wali:'guardianName',namawali:'guardianName',orangtua:'guardianName',nomorwhatsapp:'phone',nowhatsapp:'phone',whatsapp:'phone',nohp:'phone'}
  const headerIndex=matrix.findIndex(row=>Array.isArray(row)&&row.some(v=>key(v)==='nis')&&row.some(v=>['nama','namalengkap'].includes(key(v))))
  if(headerIndex<0)throw new Error('Kolom NIS dan Nama Lengkap tidak ditemukan. Gunakan template yang disediakan.')
  const columns=(matrix[headerIndex]||[]).map(v=>aliases[key(v)]||''),issues:string[]=[],seen=new Set<string>()
  const rows=matrix.slice(headerIndex+1).map((row,i)=>{const record:ImportedStudent={nis:'',nisn:'',name:'',className:'',guardianName:'',phone:'',line:headerIndex+i+2};columns.forEach((name,j)=>{if(name)record[name as keyof Omit<ImportedStudent,'line'>]=clean(row[j])});return record}).filter(r=>r.nis||r.name||r.className||r.guardianName||r.phone)
  if(!rows.length)throw new Error('Tidak ada data siswa untuk diimpor. Isi mulai baris 5 pada template.')
  if(rows.length>1000)throw new Error('Maksimal 1.000 siswa dalam satu kali impor.')
  for(const row of rows){if(!row.nis)issues.push(`Baris ${row.line}: NIS wajib diisi.`);if(!row.name)issues.push(`Baris ${row.line}: Nama Lengkap wajib diisi.`);if(row.nis&&seen.has(row.nis))issues.push(`Baris ${row.line}: NIS ${row.nis} duplikat di file.`);if(row.phone&&!/^(?:0|\+?62)\d{8,13}$/.test(row.phone.replace(/[\s()-]/g,'')))issues.push(`Baris ${row.line}: format WhatsApp tidak valid.`);seen.add(row.nis)}
  if(issues.length)throw new Error(`${issues.slice(0,5).join(' ')}${issues.length>5?` Ada ${issues.length-5} masalah lain.`:''}`)
  const [{data:existing,error:studentError},{data:currentClasses,error:classError}]=await Promise.all([supabase.from('students').select('nis').eq('school_id',school.id),supabase.from('classes').select('id,name').eq('school_id',school.id).eq('active',true)])
  if(studentError||classError)throw studentError||classError
  const existingNis=new Set((existing||[]).map(s=>s.nis)),classMap=new Map((currentClasses||[]).map(c=>[c.name.trim().toLowerCase(),c.id])),newClassNames=[...new Map(rows.filter(r=>r.className&&!classMap.has(r.className.toLowerCase())).map(r=>[r.className.toLowerCase(),r.className])).values()]
  if(newClassNames.length){const {error}=await supabase.from('classes').upsert(newClassNames.map(name=>({school_id:school.id,name})),{onConflict:'school_id,name',ignoreDuplicates:true});if(error)throw error;const {data,error:reloadError}=await supabase.from('classes').select('id,name').eq('school_id',school.id).eq('active',true);if(reloadError)throw reloadError;(data||[]).forEach(c=>classMap.set(c.name.trim().toLowerCase(),c.id))}
  const skipped=rows.filter(r=>existingNis.has(r.nis)).length,payload=rows.filter(r=>!existingNis.has(r.nis)).map(r=>({school_id:school.id,nis:r.nis,nisn:r.nisn||null,name:r.name,class_id:r.className?classMap.get(r.className.toLowerCase())||null:null,guardian_name:r.guardianName||null,guardian_phone:r.phone?.replace(/[\s()-]/g,'')||null}))
  if(!payload.length)throw new Error(`Semua ${skipped} NIS sudah ada. Tidak ada siswa baru yang ditambahkan.`)
  const {error}=await supabase.from('students').insert(payload);if(error)throw error
  const text=`${payload.length} siswa berhasil diimpor${skipped?`; ${skipped} NIS yang sudah ada dilewati.`:'.'}`;setImportNote({kind:'ok',text});notify(`${payload.length} siswa berhasil diimpor`);await load()
 }catch(error){const text=error instanceof Error?error.message:'File tidak dapat diproses.';setImportNote({kind:'error',text});notify('Impor gagal. Lihat keterangan pada halaman.','error')}finally{setImporting(false)}}
 const deactivate=async(id:string)=>{if(!confirm('Nonaktifkan siswa ini? Riwayat keuangan tetap disimpan.'))return;const {error}=await supabase.from('students').update({status:'inactive'}).eq('id',id);if(error)return notify(error.message,'error');notify('Siswa dinonaktifkan');load()}
 return <><Toolbar title="Data siswa" text={`${items.filter(i=>i.status==='active').length} siswa aktif`}><a className="secondary download-link" href="/Template-Import-Siswa-SIKAS-Pro.xlsx" download><Download/>Template Excel</a><button className="secondary" onClick={()=>fileRef.current?.click()} disabled={importing}><Upload/>{importing?'Mengimpor…':'Import Excel'}</button><input ref={fileRef} className="file-input" type="file" accept=".xlsx,.xls" onChange={importExcel}/><button className="secondary" onClick={addClass}><Plus/>Kelas</button><button className="primary small" onClick={()=>{setEditing(null);setModal(true)}}><Plus/>Tambah siswa</button></Toolbar>{importNote&&<div className={`import-note ${importNote.kind}`} role={importNote.kind==='error'?'alert':'status'}><b>{importNote.kind==='error'?'Impor belum berhasil':'Impor selesai'}</b><span>{importNote.text}</span></div>}<Card><DataTable headers={['NIS','NISN','Nama','Kelas','Wali','WhatsApp','Status','Aksi']} rows={items.map(s=>[s.nis,s.nisn||'—',s.name,s.classes?.name||'—',s.guardian_name||'—',s.guardian_phone||'—',<Badge key="s" tone={s.status==='active'?'green':'muted'}>{s.status}</Badge>,<span key="a" className="actions"><button className="link" onClick={()=>{setEditing(s);setModal(true)}}><Pencil/>Edit</button>{s.status==='active'&&<button className="link danger" onClick={()=>deactivate(s.id)}>Nonaktifkan</button>}</span>])}/></Card>{modal&&<Modal title={editing?'Edit siswa':'Tambah siswa'} onClose={()=>{setModal(false);setEditing(null)}}><form onSubmit={save}><div className="two"><Field label="NIS" name="nis" defaultValue={editing?.nis||''} required/><Field label="NISN" name="nisn" defaultValue={editing?.nisn||''}/></div><Field label="Kelas (ketik atau pilih dari riwayat)" name="class_name" list="class-history" defaultValue={editing?.classes?.name||''} placeholder="Contoh: 7A"/><datalist id="class-history">{classes.map(c=><option key={c.id} value={c.name}/>)}</datalist><Field label="Nama lengkap" name="name" defaultValue={editing?.name||''} required/><Field label="Nama wali" name="guardian_name" defaultValue={editing?.guardian_name||''}/><Field label="Nomor WhatsApp" name="guardian_phone" defaultValue={editing?.guardian_phone||''} placeholder="Contoh: 081234567890"/><button className="primary" disabled={busy}>{busy?'Menyimpan…':'Simpan siswa'}</button></form></Modal>}</>
}

function Bills({school,notify}:{school:School;notify:(s:string,k?:'ok'|'error')=>void}){
 const [items,setItems]=useState<Bill[]>([]),[students,setStudents]=useState<Student[]>([]),[cash,setCash]=useState<Cash[]>([]),[payments,setPayments]=useState<Payment[]>([]),[modal,setModal]=useState<'bill'|'pay'|'history'|null>(null),[selected,setSelected]=useState<Bill|null>(null),[editing,setEditing]=useState<Bill|null>(null),[busy,setBusy]=useState(false)
 const load=()=>Promise.all([supabase.from('bills').select('*,students(name,nis)').eq('school_id',school.id).order('created_at',{ascending:false}),supabase.from('students').select('*').eq('school_id',school.id).eq('status','active'),supabase.from('cash_accounts').select('*').eq('school_id',school.id).eq('active',true),supabase.from('payments').select('*,students(name,nis),cash_accounts(name)').eq('school_id',school.id).order('created_at',{ascending:false})]).then(([a,b,c,d])=>{const error=a.error||b.error||c.error||d.error;if(error)return notify(`Data tagihan gagal dimuat: ${error.message}`,'error');setItems((a.data||[]) as Bill[]);setStudents((b.data||[]) as Student[]);setCash((c.data||[]) as Cash[]);setPayments((d.data||[]) as Payment[])})
 useEffect(()=>{load()},[school.id])
 const add=async(e:React.FormEvent<HTMLFormElement>)=>{e.preventDefault();setBusy(true);try{const f=new FormData(e.currentTarget),payload={student_id:f.get('student'),title:f.get('title'),period:f.get('period')||null,due_date:f.get('due')||null,amount:Number(f.get('amount'))};if(editing){if(payload.amount<Number(editing.paid_amount))throw new Error(`Nominal tidak boleh kurang dari yang sudah dibayar (${money(Number(editing.paid_amount))}).`);const {error}=await supabase.from('bills').update(payload).eq('id',editing.id).eq('school_id',school.id);if(error)throw error}else{const {data:{user}}=await supabase.auth.getUser();if(!user)throw new Error('Sesi login berakhir.');const {error}=await supabase.from('bills').insert({...payload,school_id:school.id,created_by:user.id});if(error)throw error}notify(editing?'Tagihan diperbarui':'Tagihan dibuat');setModal(null);setEditing(null);await load()}catch(error){notify(`Tagihan belum tersimpan: ${error instanceof Error?error.message:'Kesalahan tidak diketahui'}`,'error')}finally{setBusy(false)}}
 const pay=async(e:React.FormEvent<HTMLFormElement>)=>{e.preventDefault();if(!selected)return;setBusy(true);try{const f=new FormData(e.currentTarget),proof=await uploadProof(school.id,f.get('proof') as File);const {data,error}=await supabase.rpc('record_payment',{target_bill:selected.id,target_cash:f.get('cash'),paid:Number(f.get('amount')),payment_method:f.get('method'),payment_proof:proof});if(error)throw error;notify(`Pembayaran berhasil · ${data}`);setModal(null);await load()}catch(error){notify(`Pembayaran gagal: ${error instanceof Error?error.message:'Kesalahan tidak diketahui'}`,'error')}finally{setBusy(false)}}
 const wa=(b:Bill)=>{const s=students.find(x=>x.id===b.student_id),phone=(s?.guardian_phone||'').replace(/^0/,'62').replace(/\D/g,'');if(!phone)return notify('Nomor WhatsApp wali belum tersedia','error');const remain=Number(b.amount)-Number(b.paid_amount),msg=encodeURIComponent(`Yth. Bapak/Ibu ${s?.guardian_name||'Wali Siswa'}, kami informasikan tagihan ${b.title} atas nama ${s?.name} sebesar ${money(remain)}. Terima kasih.`);window.open(`https://wa.me/${phone}?text=${msg}`,'_blank')}
 return <><Toolbar title="Tagihan siswa" text="Pantau lunas, sebagian, tunggakan, dan bukti pembayaran."><button className="secondary" onClick={()=>setModal('history')}><Eye/>Riwayat pembayaran</button><button className="primary small" onClick={()=>{setEditing(null);setModal('bill')}}><Plus/>Buat tagihan</button></Toolbar><Card><DataTable headers={['Siswa','Tagihan','Periode','Jatuh tempo','Nilai','Terbayar','Status','Aksi']} rows={items.map(b=>[b.students?.name||'—',b.title,b.period||'—',b.due_date||'—',money(Number(b.amount)),money(Number(b.paid_amount)),<Badge key="s" tone={b.status==='paid'?'green':b.status==='partial'?'orange':'red'}>{b.status==='paid'?'Lunas':b.status==='partial'?'Sebagian':'Belum bayar'}</Badge>,<span key="a" className="actions"><button className="link" onClick={()=>{setEditing(b);setModal('bill')}}><Pencil/>Edit</button>{b.status!=='paid'&&<button className="link" onClick={()=>{setSelected(b);setModal('pay')}}>Bayar</button>}<button className="link" onClick={()=>wa(b)}>WhatsApp</button></span>])}/></Card>{modal==='bill'&&<Modal title={editing?'Edit tagihan':'Buat tagihan'} onClose={()=>{setModal(null);setEditing(null)}}><form onSubmit={add}><label className="field"><span>Siswa</span><select name="student" defaultValue={editing?.student_id} required>{students.map(s=><option key={s.id} value={s.id}>{s.name} · {s.nis}</option>)}</select></label><Field label="Nama tagihan" name="title" defaultValue={editing?.title||''} placeholder="Contoh: SPP September" required/><div className="two"><Field label="Periode" name="period" type="month" defaultValue={editing?.period||''}/><Field label="Jatuh tempo" name="due" type="date" defaultValue={editing?.due_date||''}/></div><MoneyField label="Nominal tagihan" name="amount" min={Math.max(1,Number(editing?.paid_amount||0))} defaultValue={editing?.amount} required/><button className="primary" disabled={busy}>{busy?'Menyimpan…':'Simpan tagihan'}</button></form></Modal>}{modal==='pay'&&selected&&<Modal title={`Bayar · ${selected.students?.name}`} onClose={()=>setModal(null)}><form onSubmit={pay}><div className="bill-summary"><span>Sisa tagihan</span><b>{money(Number(selected.amount)-Number(selected.paid_amount))}</b></div><MoneyField label="Nominal pembayaran" name="amount" min={1} max={Number(selected.amount)-Number(selected.paid_amount)} required/><label className="field"><span>Masuk ke</span><select name="cash" required>{cash.map(c=><option key={c.id} value={c.id}>{c.name}</option>)}</select></label><label className="field"><span>Metode</span><select name="method"><option>Tunai</option><option>Transfer bank</option><option>E-Wallet</option><option>QRIS</option></select></label><Field label="Foto bukti pembayaran (opsional, maks. 5 MB)" name="proof" type="file" accept="image/jpeg,image/png,image/webp,application/pdf"/><button className="primary" disabled={busy}>{busy?'Memproses…':'Simpan pembayaran'}</button></form></Modal>}{modal==='history'&&<Modal title="Riwayat pembayaran" onClose={()=>setModal(null)}><DataTable headers={['Tanggal','Kwitansi','Siswa','Masuk ke','Nominal','Bukti']} rows={payments.map(p=>[p.payment_date,p.receipt_number,p.students?.name||'—',p.cash_accounts?.name||'—',money(Number(p.amount)),<button key="v" className="icon table-icon" title="Lihat bukti" aria-label={`Lihat bukti ${p.receipt_number}`} onClick={()=>showProof(p.proof_path,notify)}><Eye/></button>])}/></Modal>}</>
}

function Budget({school,notify}:{school:School;notify:(s:string,k?:'ok'|'error')=>void}){
 const [items,setItems]=useState<{id:string;code:string;name:string;funding_source:string;budget:number}[]>([]),[tx,setTx]=useState<Tx[]>([]),[modal,setModal]=useState(false),[editing,setEditing]=useState<{id:string;code:string;name:string;funding_source:string;budget:number}|null>(null),[busy,setBusy]=useState(false)
 const load=()=>Promise.all([supabase.from('activities').select('*').eq('school_id',school.id),supabase.from('transactions').select('*').eq('school_id',school.id).eq('kind','expense').eq('status','posted')]).then(([a,b])=>{setItems(a.data||[]);setTx((b.data||[]) as Tx[])})
 useEffect(()=>{load()},[school.id])
 const save=async(e:React.FormEvent<HTMLFormElement>)=>{e.preventDefault();setBusy(true);const f=new FormData(e.currentTarget),payload={name:f.get('name'),funding_source:f.get('source')||null,budget:Number(f.get('budget'))};const result=editing?await supabase.from('activities').update(payload).eq('id',editing.id).eq('school_id',school.id):await supabase.from('activities').insert({...payload,school_id:school.id,code:null});setBusy(false);if(result.error)return notify(`Anggaran belum tersimpan: ${result.error.message}`,'error');notify(editing?'Anggaran diperbarui':'Kegiatan dan pagu ditambahkan');setModal(false);setEditing(null);load()}
 return <><Toolbar title="Anggaran kegiatan" text="Kode dibuat otomatis; realisasi dihitung langsung dari pengeluaran."><button className="primary small" onClick={()=>{setEditing(null);setModal(true)}}><Plus/>Tambah kegiatan</button></Toolbar><div className="cards-list">{items.length?items.map(i=>{const used=tx.filter(t=>t.activity_id===i.id).reduce((a,b)=>a+Number(b.amount),0),pct=i.budget?Math.min(100,used/i.budget*100):0;return <Card key={i.id}><div className="budget-head"><div><small>{i.code} · {i.funding_source||'Dana sekolah'}</small><h3>{i.name}</h3></div><span className="actions"><button className="link" onClick={()=>{setEditing(i);setModal(true)}}><Pencil/>Edit</button><Badge tone={used>i.budget?'red':pct>80?'orange':'green'}>{used>i.budget?'Melebihi':pct>80?'Hampir habis':'Aman'}</Badge></span></div><div className="progress"><i style={{width:`${pct}%`}}/></div><div className="budget-values"><span>Realisasi <b>{money(used)}</b></span><span>Sisa <b>{money(i.budget-used)}</b></span><span>Pagu <b>{money(i.budget)}</b></span></div></Card>}):<Empty text="Belum ada anggaran kegiatan."/>}</div>{modal&&<Modal title={editing?'Edit kegiatan':'Tambah kegiatan'} onClose={()=>{setModal(false);setEditing(null)}}><form onSubmit={save}>{editing&&<div className="generated-code"><span>Kode otomatis</span><b>{editing.code}</b></div>}<Field label="Sumber dana" name="source" defaultValue={editing?.funding_source||''} placeholder="Contoh: BOS Reguler"/><Field label="Nama kegiatan" name="name" defaultValue={editing?.name||''} placeholder="Contoh: Pengadaan buku perpustakaan" required/><MoneyField label="Pagu anggaran" name="budget" min={0} defaultValue={editing?.budget} required/><button className="primary" disabled={busy}>{busy?'Menyimpan…':'Simpan kegiatan'}</button></form></Modal>}</>
}

function Reports({school,notify}:{school:School;notify:(s:string,k?:'ok'|'error')=>void}){
 const [tx,setTx]=useState<Tx[]>([]),[month,setMonth]=useState(new Date().toISOString().slice(0,7))
 useEffect(()=>{supabase.from('transactions').select('*').eq('school_id',school.id).eq('status','posted').order('tx_date').then(({data})=>setTx((data||[]) as Tx[]))},[school.id])
 const rows=tx.filter(t=>t.tx_date.startsWith(month)),income=rows.filter(t=>t.kind==='income').reduce((a,b)=>a+Number(b.amount),0),expense=rows.filter(t=>t.kind==='expense').reduce((a,b)=>a+Number(b.amount),0)
 const pdf=async()=>{void supabase.rpc('track_report',{target_school:school.id});const [{default:jsPDF},{default:autoTable}]=await Promise.all([import('jspdf'),import('jspdf-autotable')]);const doc=new jsPDF();doc.setFontSize(16);doc.text('BUKU KAS UMUM',105,18,{align:'center'});doc.setFontSize(10);doc.text(`${school.name} · Periode ${month}`,105,25,{align:'center'});autoTable(doc,{startY:32,head:[['Tanggal','Nomor','Keterangan','Masuk','Keluar']],body:rows.map(t=>[t.tx_date,t.number,t.description,t.kind==='income'?money(Number(t.amount)):'—',t.kind==='expense'?money(Number(t.amount)):'—']),foot:[['','','TOTAL',money(income),money(expense)]]});doc.save(`BKU-${school.name}-${month}.pdf`);notify('PDF berhasil dibuat')}
 const excel=async()=>{void supabase.rpc('track_report',{target_school:school.id});const XLSX=await import('xlsx');const data=rows.map(t=>({Tanggal:t.tx_date,Nomor:t.number,Keterangan:t.description,Kategori:t.category,Pemasukan:t.kind==='income'?t.amount:0,Pengeluaran:t.kind==='expense'?t.amount:0})),ws=XLSX.utils.json_to_sheet(data),wb=XLSX.utils.book_new();XLSX.utils.book_append_sheet(wb,ws,'BKU');XLSX.writeFile(wb,`BKU-${school.name}-${month}.xlsx`);notify('Excel berhasil dibuat')}
 return <><Toolbar title="Pusat laporan" text="Preview dan unduhan menggunakan data yang sama."><label className="month"><span>Periode</span><input type="month" value={month} onChange={e=>setMonth(e.target.value)}/></label></Toolbar><div className="stats"><Stat label="Pemasukan periode" value={money(income)} tone="green"/><Stat label="Pengeluaran periode" value={money(expense)} tone="red"/><Stat label="Surplus / defisit" value={money(income-expense)} tone="blue"/><Stat label="Jumlah transaksi" value={String(rows.length)} tone="orange"/></div><Card title="Preview Buku Kas Umum" actions={<><button className="secondary" onClick={excel}><Download/>Excel</button><button className="primary small" onClick={pdf}><Download/>PDF</button></>}><DataTable headers={['Tanggal','Nomor','Keterangan','Kategori','Pemasukan','Pengeluaran']} rows={rows.map(t=>[t.tx_date,t.number,t.description,t.category,t.kind==='income'?money(Number(t.amount)):'—',t.kind==='expense'?money(Number(t.amount)):'—'])}/></Card></>
}

function Team({school,notify}:{school:School;notify:(s:string,k?:'ok'|'error')=>void}){
 const [members,setMembers]=useState<{user_id:string;role:string;status:string;profiles?:{full_name:string;username:string}}[]>([]),[invites,setInvites]=useState<{id:string;expires_at:string;accepted_at:string|null;revoked_at:string|null}[]>([])
 const load=()=>Promise.all([supabase.from('school_members').select('*,profiles(full_name,username)').eq('school_id',school.id),supabase.from('invitations').select('*').eq('school_id',school.id).order('created_at',{ascending:false})]).then(([a,b])=>{setMembers(a.data||[]);setInvites(b.data||[])})
 useEffect(()=>{load()},[school.id])
 const invite=async()=>{const {data,error}=await supabase.rpc('create_invitation',{target_school:school.id});if(error)return notify(`Link undangan gagal dibuat: ${error.message}`,'error');const url=`${location.origin}/?invite=${data}`;try{await navigator.clipboard.writeText(url);notify('Link undangan disalin. Berlaku 7 hari.')}catch{prompt('Salin link undangan ini:',url);notify('Link berhasil dibuat. Salin dari kotak yang muncul.')}load()}
 const disable=async(uid:string)=>{if(!confirm('Nonaktifkan anggota ini?'))return;const {error}=await supabase.from('school_members').update({status:'inactive'}).eq('school_id',school.id).eq('user_id',uid);if(error)return notify(error.message,'error');notify('Anggota dinonaktifkan');load()}
 return <><Toolbar title="Tim sekolah" text="Kelola akses Bendahara / Staf Keuangan."><button className="primary small" onClick={invite}><Plus/>Buat link undangan</button></Toolbar><div className="grid-2"><Card title="Anggota"><div className="quick-list">{members.map(m=><p key={m.user_id}><span><b>{m.profiles?.full_name||'Pengguna'}</b><small>@{m.profiles?.username} · {m.role==='principal'?'Kepala Sekolah':'Bendahara/Staf'}</small></span><span><Badge tone={m.status==='active'?'green':'muted'}>{m.status}</Badge>{m.role==='staff'&&m.status==='active'&&<button className="link danger" onClick={()=>disable(m.user_id)}>Nonaktifkan</button>}</span></p>)}</div></Card><Card title="Riwayat undangan"><div className="quick-list">{invites.length?invites.map(i=><p key={i.id}><span>Dibuat untuk Bendahara/Staf<small>Kedaluwarsa {new Date(i.expires_at).toLocaleDateString('id-ID')}</small></span><Badge tone={i.accepted_at?'green':i.revoked_at?'muted':'orange'}>{i.accepted_at?'Diterima':i.revoked_at?'Batal':'Aktif'}</Badge></p>):<Empty text="Belum ada undangan."/>}</div></Card></div></>
}

function SchoolSettings({school,role,notify}:{school:School;role:'principal'|'staff';notify:(s:string,k?:'ok'|'error')=>void}){
 const [detail,setDetail]=useState<School>(school),[members,setMembers]=useState<{user_id:string;role:string;status:string;created_at:string;profiles?:{full_name:string;username:string;last_seen_at:string|null}|null}[]>([]),[busy,setBusy]=useState(false)
 useEffect(()=>{Promise.all([supabase.from('schools').select('*').eq('id',school.id).single(),supabase.from('school_members').select('user_id,role,status,created_at,profiles(full_name,username,last_seen_at)').eq('school_id',school.id).order('created_at')]).then(([a,b])=>{if(a.data)setDetail(a.data as School);if(b.data)setMembers(b.data as unknown as typeof members);if(a.error||b.error)notify(`Pengaturan gagal dimuat: ${(a.error||b.error)?.message}`,'error')})},[school.id])
 const save=async(e:React.FormEvent<HTMLFormElement>)=>{e.preventDefault();setBusy(true);const f=new FormData(e.currentTarget),payload={name:f.get('name'),npsn:f.get('npsn')||null,school_level:f.get('level')||null,academic_year:f.get('year'),principal_name:f.get('principal')||null,treasurer_name:f.get('treasurer')||null,address:f.get('address')||null,city:f.get('city')||null,province:f.get('province')||null,postal_code:f.get('postal_code')||null,phone:f.get('phone')||null,email:f.get('email')||null},{data,error}=await supabase.from('schools').update(payload).eq('id',school.id).select('*').single();setBusy(false);if(error)return notify(`Pengaturan belum tersimpan: ${error.message}`,'error');setDetail(data as School);notify('Informasi sekolah berhasil diperbarui')}
 return <div className="settings-grid"><Card title="Informasi sekolah"><form className="settings-form" onSubmit={save}><Field label="Nama sekolah" name="name" defaultValue={detail.name} disabled={role!=='principal'} required/><div className="two"><Field label="NPSN" name="npsn" defaultValue={detail.npsn||''} disabled={role!=='principal'} placeholder="Contoh: 20512345"/><Field label="Jenjang sekolah" name="level" defaultValue={detail.school_level||''} disabled={role!=='principal'} placeholder="Contoh: SD / SMP / SMA"/></div><div className="two"><Field label="Tahun pelajaran" name="year" defaultValue={detail.academic_year} disabled={role!=='principal'} required/><Field label="Nama kepala sekolah" name="principal" defaultValue={detail.principal_name||''} disabled={role!=='principal'}/></div><Field label="Nama bendahara" name="treasurer" defaultValue={detail.treasurer_name||''} disabled={role!=='principal'}/><Field label="Alamat lengkap" name="address" defaultValue={detail.address||''} disabled={role!=='principal'} placeholder="Jalan, nomor, desa/kelurahan, kecamatan"/><div className="two"><Field label="Kota / Kabupaten" name="city" defaultValue={detail.city||''} disabled={role!=='principal'}/><Field label="Provinsi" name="province" defaultValue={detail.province||''} disabled={role!=='principal'}/></div><div className="two"><Field label="Kode pos" name="postal_code" defaultValue={detail.postal_code||''} disabled={role!=='principal'}/><Field label="Telepon sekolah" name="phone" defaultValue={detail.phone||''} disabled={role!=='principal'} placeholder="Contoh: 0341xxxxxx"/></div><Field label="Email sekolah" name="email" type="email" defaultValue={detail.email||''} disabled={role!=='principal'} placeholder="Contoh: sekolah@example.sch.id"/>{role==='principal'?<button className="primary" disabled={busy}>{busy?'Menyimpan…':'Simpan perubahan'}</button>:<p className="hint">Informasi sekolah hanya dapat diedit oleh Kepala Sekolah.</p>}</form></Card><Card title="Akun yang terhubung"><div className="quick-list">{members.map(m=><p key={m.user_id}><span><b>{m.profiles?.full_name||'Pengguna'}</b><small>@{m.profiles?.username} · bergabung {new Date(m.created_at).toLocaleDateString('id-ID')}</small></span><span><Badge tone={m.status==='active'?'green':'muted'}>{m.role==='principal'?'Kepala Sekolah':'Bendahara/Staf'}</Badge><small>{m.profiles?.last_seen_at?`Aktif ${new Date(m.profiles.last_seen_at).toLocaleString('id-ID')}`:'Belum tercatat login'}</small></span></p>)}</div></Card></div>
}
function Owner(){return <Card title="Owner Control"><Empty text="Panel pemilik tersedia pada akun Super Admin khusus."/></Card>}

function OwnerApp({onLogout}:{onLogout:()=>void}){const [schools,setSchools]=useState<(School&{subscriptions?:{status:string;plan:string}|null;usage_metrics?:{students_count:number;transactions_count:number;reports_count:number;storage_bytes:number;last_active_at:string|null}|null})[]>([]),[people,setPeople]=useState<{id:string;full_name:string;username:string;last_seen_at:string|null}[]>([]);useEffect(()=>{Promise.all([supabase.from('schools').select('*,subscriptions(status,plan),usage_metrics(students_count,transactions_count,reports_count,storage_bytes,last_active_at)').order('created_at',{ascending:false}),supabase.from('profiles').select('id,full_name,username,last_seen_at').order('last_seen_at',{ascending:false,nullsFirst:false})]).then(([a,b])=>{setSchools(a.data||[]);setPeople(b.data||[])})},[]);return <div className="owner-page"><header><Brand compact/><span className="grow"/><Badge tone="orange">SUPER ADMIN</Badge><button className="secondary" onClick={onLogout}><LogOut/>Keluar</button></header><main className="content"><Toolbar title="Owner Control" text="Pemantauan produk tanpa membuka data keuangan sekolah."/><div className="stats"><Stat label="Sekolah terdaftar" value={String(schools.length)} tone="blue"/><Stat label="Total pengguna" value={String(people.length)} tone="green"/><Stat label="Sekolah aktif" value={String(schools.filter(s=>s.subscriptions?.status==='active'||s.subscriptions?.status==='trial').length)} tone="orange"/><Stat label="Total penyimpanan" value={`${(schools.reduce((a,s)=>a+Number(s.usage_metrics?.storage_bytes||0),0)/1048576).toFixed(1)} MB`} tone="red"/></div><Card title="Daftar pelanggan"><DataTable headers={['Sekolah','NPSN','Paket','Status','Siswa','Transaksi','Laporan','Aktif terakhir']} rows={schools.map(s=>[s.name,s.npsn||'—',s.subscriptions?.plan||'trial',<Badge key="x" tone="green">{s.subscriptions?.status||'trial'}</Badge>,String(s.usage_metrics?.students_count||0),String(s.usage_metrics?.transactions_count||0),String(s.usage_metrics?.reports_count||0),s.usage_metrics?.last_active_at?new Date(s.usage_metrics.last_active_at).toLocaleString('id-ID'):'—'])}/></Card><Card title="Akses pengguna terbaru"><DataTable headers={['Nama','Username','Terakhir masuk']} rows={people.slice(0,20).map(p=>[p.full_name,`@${p.username}`,p.last_seen_at?new Date(p.last_seen_at).toLocaleString('id-ID'):'Belum tercatat'])}/></Card></main></div>}

function Toolbar({title,text,children}:{title:string;text:string;children?:React.ReactNode}){return <div className="toolbar"><div><h2>{title}</h2><p>{text}</p></div><div className="toolbar-actions">{children}</div></div>}
function Stat({label,value,tone}:{label:string;value:string;tone:string}){return <div className={`stat ${tone}`}><small>{label}</small><b>{value}</b></div>}
function Card({title,actions,children}:{title?:string;actions?:React.ReactNode;children:React.ReactNode}){return <section className="card">{title&&<div className="card-title"><h3>{title}</h3><div>{actions}</div></div>}{children}</section>}
function Badge({tone,children}:{tone:string;children:React.ReactNode}){return <span className={`badge ${tone}`}>{children}</span>}
function Field(props:React.InputHTMLAttributes<HTMLInputElement>&{label:string}){const{label,...rest}=props;return <label className="field"><span>{label}</span><input {...rest}/></label>}
function MoneyField({label,...props}:React.InputHTMLAttributes<HTMLInputElement>&{label:string}){return <Field {...props} label={label} type="number" inputMode="numeric" placeholder={props.placeholder||'Contoh: 150000 (untuk Rp150.000)'} step="1"/>}
function Modal({title,onClose,children}:{title:string;onClose:()=>void;children:React.ReactNode}){return <div className="modal-wrap"><button className="backdrop" aria-label="Tutup dialog" onClick={onClose}/><section className="modal" role="dialog" aria-modal="true" aria-label={title}><header><h2>{title}</h2><button className="icon" aria-label="Tutup" onClick={onClose}><X/></button></header>{children}</section></div>}
function Empty({text}:{text:string}){return <div className="empty"><BookOpen/><p>{text}</p></div>}
function DataTable({headers,rows}:{headers:string[];rows:React.ReactNode[][]}){return rows.length?<div className="table-wrap"><table><thead><tr>{headers.map(h=><th key={h}>{h}</th>)}</tr></thead><tbody>{rows.map((r,i)=><tr key={i}>{r.map((v,j)=><td key={j} data-label={headers[j]}>{v}</td>)}</tr>)}</tbody></table></div>:<Empty text="Belum ada data untuk ditampilkan."/>}
